import { serve } from "https://deno.land/std@0.190.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.50.0";
import {
  assertAdminManagerOrServiceRole,
  authorizationErrorResponse,
} from '../_shared/edgeAuthorization.ts';
import { disabledHostawayResponse, isHostawayIntegrationEnabled } from '../_shared/disabledIntegration.ts';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

interface CronRequest {
  action: 'sync' | 'setup' | 'cleanup';
  scheduleId?: string;
}

const convertToCronExpression = (hour: number, minute: number, timezone: string = 'Europe/Madrid'): string => {
  // Cron expression: minute hour * * *
  return `${minute} ${hour} * * *`;
};

const setupCronJobs = async (supabase: any) => {
  console.log('🔄 Setting up cron jobs for active schedules...');
  
  // Obtener todos los schedules activos
  const { data: schedules, error } = await supabase
    .from('hostaway_sync_schedules')
    .select('*')
    .eq('is_active', true)
    .order('hour', { ascending: true });

  if (error) {
    throw new Error(`Error fetching schedules: ${error.message}`);
  }

  console.log(`📋 Found ${schedules?.length || 0} active schedules`);

  const supabaseUrl = Deno.env.get('SUPABASE_URL');
  const supabaseAnonKey = Deno.env.get('SUPABASE_ANON_KEY');
  
  if (!supabaseUrl || !supabaseAnonKey) {
    throw new Error('Missing SUPABASE_URL or SUPABASE_ANON_KEY');
  }

  // Crear nuevos trabajos cron para cada schedule activo
  const results = [];
  for (const schedule of schedules || []) {
    const jobName = `hostaway_sync_${schedule.id.replace(/-/g, '_')}`;
    const cronExpression = convertToCronExpression(schedule.hour, schedule.minute, schedule.timezone);
    const functionUrl = `${supabaseUrl}/functions/v1/hostaway-sync`;
    const authHeader = `{"Content-Type": "application/json", "Authorization": "Bearer ${supabaseAnonKey}"}`;
    const requestBody = JSON.stringify({
      scheduleId: schedule.id,
      scheduleName: schedule.name,
      triggeredBy: 'automatic'
    });
    
    try {
      const { data: cronResult, error: cronError } = await supabase.rpc('manage_hostaway_cron_job', {
        job_name: jobName,
        cron_schedule: cronExpression,
        function_url: functionUrl,
        auth_header: authHeader,
        request_body: requestBody
      });

      if (cronError) {
        console.error(`❌ Error creating cron job for ${schedule.name}:`, cronError);
        results.push({ schedule: schedule.name, success: false, error: cronError.message });
      } else if (cronResult?.success === false) {
        console.error(`❌ Cron job failed for ${schedule.name}:`, cronResult.error);
        results.push({ schedule: schedule.name, success: false, error: cronResult.error });
      } else {
        console.log(`✅ Cron job created for ${schedule.name} at ${schedule.hour}:${schedule.minute.toString().padStart(2, '0')}`);
        console.log(`   Job ID: ${cronResult?.job_id}, Schedule: ${cronExpression}`);
        results.push({ schedule: schedule.name, success: true, jobId: cronResult?.job_id });
      }
    } catch (jobError: any) {
      console.error(`❌ Failed to create cron job for ${schedule.name}:`, jobError);
      results.push({ schedule: schedule.name, success: false, error: jobError.message });
    }
  }

  return { 
    success: true, 
    schedulesProcessed: schedules?.length || 0,
    results: results
  };
};

serve(async (req) => {
  console.log('🚀 manage-hostaway-cron started');

  if (req.method === 'OPTIONS') {
    return new Response(null, { headers: corsHeaders });
  }

  if (!isHostawayIntegrationEnabled()) {
    return disabledHostawayResponse(corsHeaders);
  }

  try {
    const supabaseUrl = Deno.env.get('SUPABASE_URL');
    const supabaseKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');
    
    if (!supabaseUrl || !supabaseKey) {
      throw new Error('Missing Supabase environment variables');
    }

    const supabase = createClient(supabaseUrl, supabaseKey);
    await assertAdminManagerOrServiceRole(req, supabase, supabaseKey);
    
    const requestBody: CronRequest = await req.json().catch(() => ({ action: 'setup' }));
    const { action, scheduleId } = requestBody;

    console.log(`📋 Action: ${action}, ScheduleId: ${scheduleId || 'N/A'}`);

    switch (action) {
      case 'sync':
        // Ejecutar sincronización para un schedule específico
        if (!scheduleId) {
          throw new Error('scheduleId is required for sync action');
        }

        const { data: schedule } = await supabase
          .from('hostaway_sync_schedules')
          .select('*')
          .eq('id', scheduleId)
          .single();

        if (!schedule) {
          throw new Error('Schedule not found');
        }

        const { data: syncResult, error: syncError } = await supabase.functions.invoke('hostaway-sync-with-retry', {
          body: {
            scheduleId: schedule.id,
            scheduleName: schedule.name,
            isRetry: false
          }
        });

        if (syncError) {
          throw syncError;
        }

        return new Response(JSON.stringify({ 
          success: true, 
          action: 'sync',
          schedule: schedule.name,
          result: syncResult 
        }), {
          status: 200,
          headers: { ...corsHeaders, 'Content-Type': 'application/json' }
        });

      case 'setup':
        // Configurar todos los cron jobs
        const setupResult = await setupCronJobs(supabase);
        
        return new Response(JSON.stringify({
          success: true,
          action: 'setup',
          ...setupResult
        }), {
          status: 200,
          headers: { ...corsHeaders, 'Content-Type': 'application/json' }
        });

      case 'cleanup':
        // Limpiar trabajos cron (implementación básica)
        console.log('🗑️ Cleaning up cron jobs...');
        
        return new Response(JSON.stringify({
          success: true,
          action: 'cleanup',
          message: 'Cron cleanup completed'
        }), {
          status: 200,
          headers: { ...corsHeaders, 'Content-Type': 'application/json' }
        });

      default:
        throw new Error(`Unknown action: ${action}`);
    }

  } catch (error) {
    const authResponse = authorizationErrorResponse(error, corsHeaders);
    if (authResponse) return authResponse;
    console.error('❌ Error in manage-hostaway-cron:', error);
    
    return new Response(JSON.stringify({ 
      success: false, 
      error: error.message 
    }), {
      status: 500,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' }
    });
  }
});

import type { SupabaseClient } from 'https://esm.sh/@supabase/supabase-js@2.50.0';

export type PrivilegedEdgeActor = {
  kind: 'service-role' | 'user' | 'cron';
  userId?: string;
  role?: string;
};

function extractBearer(req: Request): string | null {
  const header = req.headers.get('Authorization') || '';
  const match = header.match(/^Bearer\s+(.+)$/i);
  return match?.[1]?.trim() || null;
}

async function secretsMatch(provided: string | null, expected: string): Promise<boolean> {
  if (!provided || !expected) return false;
  const encoder = new TextEncoder();
  const [providedHash, expectedHash] = await Promise.all([
    crypto.subtle.digest('SHA-256', encoder.encode(provided)),
    crypto.subtle.digest('SHA-256', encoder.encode(expected)),
  ]);
  const providedBytes = new Uint8Array(providedHash);
  const expectedBytes = new Uint8Array(expectedHash);
  let difference = 0;
  for (let index = 0; index < providedBytes.length; index += 1) {
    difference |= providedBytes[index] ^ expectedBytes[index];
  }
  return difference === 0;
}

export async function assertAdminManagerOrServiceRole(
  req: Request,
  supabaseAdmin: SupabaseClient,
  serviceRoleKey: string,
  options?: {
    dedicatedSecret?: {
      headerName: string;
      value: string;
      actorKind: 'cron';
    };
  },
): Promise<PrivilegedEdgeActor> {
  const token = extractBearer(req);
  if (!token) {
    throw new Response('Missing authorization', { status: 401 });
  }

  if (serviceRoleKey && token === serviceRoleKey) {
    return { kind: 'service-role' };
  }

  const dedicatedSecret = options?.dedicatedSecret;
  if (
    dedicatedSecret
    && await secretsMatch(req.headers.get(dedicatedSecret.headerName), dedicatedSecret.value)
  ) {
    return { kind: dedicatedSecret.actorKind };
  }

  const { data: userData, error: userError } = await supabaseAdmin.auth.getUser(token);
  if (userError || !userData.user) {
    throw new Response('Invalid session', { status: 401 });
  }

  const { data: roles, error: roleError } = await supabaseAdmin
    .from('user_roles')
    .select('role')
    .eq('user_id', userData.user.id)
    .in('role', ['admin', 'manager'])
    .limit(1);

  if (roleError) {
    console.error('Unable to verify privileged Edge Function role:', roleError);
    throw new Response('Unable to verify authorization', { status: 500 });
  }

  const role = roles?.[0]?.role;
  if (!role) {
    throw new Response('Forbidden', { status: 403 });
  }

  return {
    kind: 'user',
    userId: userData.user.id,
    role,
  };
}

export function authorizationErrorResponse(error: unknown, corsHeaders: HeadersInit): Response | null {
  if (!(error instanceof Response)) return null;
  return new Response(error.body, {
    status: error.status,
    statusText: error.statusText,
    headers: { ...corsHeaders, 'Content-Type': 'text/plain; charset=utf-8' },
  });
}

export const HOSTAWAY_INTEGRATION_DISABLED = 'HOSTAWAY_INTEGRATION_DISABLED';

export function isHostawayIntegrationEnabled(): boolean {
  return false;
}

export function disabledHostawayResponse(corsHeaders: Record<string, string>): Response {
  return new Response(
    JSON.stringify({
      success: false,
      code: HOSTAWAY_INTEGRATION_DISABLED,
      error: 'La integración con Hostaway está desactivada y conservada para futuros clientes.',
    }),
    {
      status: 410,
      headers: { ...corsHeaders, 'Content-Type': 'application/json' },
    },
  );
}
